import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    for i in range(3, math.isqrt(n) + 1, 2):
        if n % i == 0:
            return False
    return True
```

This checks divisibility only up to `sqrt(n)` (using integer `isqrt`), with even numbers handled separately for a small speedup.
